use vstd::prelude::*;
use vstd::vec::Vec;

verus! {

// Verify that for two non-empty vectors a and b of i32,
// returns true iff there exists an element common to both.

fn has_common_element(a: &Vec<i32>, b: &Vec<i32>) -> (result: bool)
    ensures {
        // correctness specification: result is true iff
        // ∃ i, j within bounds such that a[i] == b[j]
        result <==> exists(|i: int, j: int| 0 <= i && i < a.len() as int && 0 <= j && j < b.len() as int && a[i as usize] == b[j as usize])
    }
    requires {
        // inputs are non-empty as per problem statement
        a.len() > 0 && b.len() > 0
    }
{
    // We will check each element in `a` against all elements in `b`.
    // If any common element is found, return true.
    // Otherwise, return false.

    let mut i: int = 0;
    while i < a.len() as int
        invariant 0 <= i && i <= a.len() as int
        decreases a.len() as int - i;
    {
        // For current a[i], check b completely
        let ai = a[i as usize];

        let mut j: int = 0;
        while j < b.len() as int
            invariant 0 <= j && j <= b.len() as int
            decreases b.len() as int - j;
        {
            if ai == b[j as usize] {
                // common element found
                return true;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    // If we finish loops, no common element found
    return false;
}

}